const input = $input.first().json;
const execution = input?.execution ?? {};
const workflow = input?.workflow ?? {};
const error = execution?.error ?? input?.error ?? {};
const name = workflow?.name ?? input?.workflowName ?? 'Unknown workflow';
const lower = String(name).toLowerCase();

// Provider is the vendor the workflow talks to, so a failure lands next to that vendor's sync rows.
const provider =
  lower.includes('aimfox') ? 'aimfox' :
  lower.includes('winnr')  ? 'winnr'  :
  (lower.includes('bison') || lower.includes('ooo') || lower.includes('nrr') ||
   lower.includes('mql') || lower.includes('daily stats') || lower.includes('campaign')) ? 'bison' :
  'n8n';

return [{ json: {
  provider,
  n8n_execution_id: String(execution?.id ?? input?.executionId ?? ('unknown-' + name)),
  workflow_id: String(workflow?.id ?? ''),
  workflow_name: String(name),
  last_node: String(execution?.lastNodeExecuted ?? ''),
  error_message: String(error?.message ?? input?.message ?? 'Unknown workflow failure'),
  error_stack: error?.stack ? String(error.stack).slice(0, 2000) : null,
} }];
